import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.I6s8z2kk.js";const g=JSON.parse('{"title":"Homepage sections and banners","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/homepage.md","filePath":"user/admin/homepage.md"}'),o={name:"user/admin/homepage.md"};function r(i,e,d,h,c,l){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="homepage-sections-and-banners" tabindex="-1">Homepage sections and banners <a class="header-anchor" href="#homepage-sections-and-banners" aria-label="Permalink to &quot;Homepage sections and banners&quot;">​</a></h1><p>The homepage is a list of <strong>sections</strong>. Each section has a type, a title, a position, and an optional publishing window.</p><h2 id="section-types" tabindex="-1">Section types <a class="header-anchor" href="#section-types" aria-label="Permalink to &quot;Section types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>What clients see</th></tr></thead><tbody><tr><td><strong>Banner carousel</strong></td><td>A carousel of banners</td></tr><tr><td><strong>Curated centers</strong></td><td>Centers you pick, in the order you set</td></tr><tr><td><strong>Curated services</strong></td><td>Services you pick, in the order you set. Services show their price, and the discounted price while an offer runs.</td></tr><tr><td><strong>Curated promotions</strong></td><td>Running promotions you pick</td></tr><tr><td><strong>Curated campaigns</strong></td><td>Running campaigns you pick</td></tr><tr><td><strong>Top centers</strong></td><td>Most popular centers, or the nearest first when the client shares their location</td></tr></tbody></table><p>A section&#39;s <strong>type cannot be changed</strong> after it is created. Create a new one instead.</p><h2 id="what-actually-shows" tabindex="-1">What actually shows <a class="header-anchor" href="#what-actually-shows" aria-label="Permalink to &quot;What actually shows&quot;">​</a></h2><p>Even if you pick it, an item only shows when it is live:</p><ul><li>centers must be <strong>visible and active</strong></li><li>services must be <strong>active</strong> and belong to a visible center</li><li>promotions must be running and still have uses left</li><li>campaigns must be running</li><li>the section and each item must be <strong>published</strong> and inside their dates</li></ul><p>A section with nothing to show is hidden.</p><h2 id="banners" tabindex="-1">Banners <a class="header-anchor" href="#banners" aria-label="Permalink to &quot;Banners&quot;">​</a></h2><p>Banners belong to <strong>banner carousel</strong> sections only. Each banner has an image, an optional action (open a center, service, promotion, campaign or a link) and an optional publishing window.</p><h2 id="ordering-and-picking" tabindex="-1">Ordering and picking <a class="header-anchor" href="#ordering-and-picking" aria-label="Permalink to &quot;Ordering and picking&quot;">​</a></h2><p>Drag sections into order (<strong>Reorder</strong>). For a curated section, open <strong>Items</strong>, search the candidates and choose them.</p><h2 id="changes-show-quickly" tabindex="-1">Changes show quickly <a class="header-anchor" href="#changes-show-quickly" aria-label="Permalink to &quot;Changes show quickly&quot;">​</a></h2><p>Edits appear on the next load of the app. Scheduled items appear on time by themselves.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p><strong>Analytics → Home content</strong> shows how often sections and banners are viewed and tapped. It is aggregate only; no individual client is tracked.</p>',17)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
